ALTER TABLE "team_members" DROP CONSTRAINT "team_members_added_via";--> statement-breakpoint
ALTER TABLE "notifications" DROP CONSTRAINT "notifications_kind";--> statement-breakpoint
ALTER TABLE "notifications" DROP CONSTRAINT "notifications_shape";--> statement-breakpoint
ALTER TABLE "notifications" DROP CONSTRAINT "notifications_actor";--> statement-breakpoint
ALTER TABLE "team_members" ADD CONSTRAINT "team_members_added_via" CHECK ("team_members"."added_via" IS NULL OR "team_members"."added_via" IN ('skill_reviewer_grant', 'site_admin') OR "team_members"."added_via" ~ '^idp:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$');--> statement-breakpoint
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_kind" CHECK ("notifications"."kind" IN ('schedule.run.succeeded', 'schedule.run.failed', 'schedule.run.interrupted', 'schedule.run.skipped_actions', 'schedule.paused', 'skill.member_add.blocked', 'skill.deprecated', 'skill.version.deprecated', 'skill.version.withdrawn', 'skill.version.revoked', 'skill.version.unrevoked', 'skill.version.site_published', 'team.member.added'));--> statement-breakpoint
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_shape" CHECK (("notifications"."kind" = 'schedule.paused' AND "notifications"."thread_id" IS NULL AND "notifications"."run_id" IS NULL AND "notifications"."paused_by" IS NOT NULL AND "notifications"."skill_id" IS NULL AND "notifications"."skill_semver" IS NULL)
        OR ("notifications"."kind" LIKE 'team.%' AND "notifications"."schedule_id" IS NULL AND "notifications"."thread_id" IS NULL AND "notifications"."run_id" IS NULL AND "notifications"."paused_by" IS NULL AND "notifications"."skill_id" IS NULL AND "notifications"."skill_semver" IS NULL)
        OR ("notifications"."kind" LIKE 'skill.%' AND "notifications"."schedule_id" IS NULL AND "notifications"."thread_id" IS NULL AND "notifications"."run_id" IS NULL AND "notifications"."paused_by" IS NULL AND "notifications"."skill_id" IS NOT NULL
          AND ("notifications"."skill_semver" IS NOT NULL) = ("notifications"."kind" LIKE 'skill.version.%'))
        OR ("notifications"."kind" <> 'schedule.paused' AND "notifications"."kind" NOT LIKE 'skill.%' AND "notifications"."kind" NOT LIKE 'team.%' AND "notifications"."thread_id" IS NOT NULL AND "notifications"."run_id" IS NOT NULL AND "notifications"."paused_by" IS NULL AND "notifications"."skill_id" IS NULL AND "notifications"."skill_semver" IS NULL));--> statement-breakpoint
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_actor" CHECK (("notifications"."kind" IN ('skill.version.site_published', 'team.member.added')) = ("notifications"."actor_user_id" IS NOT NULL));